class N:
 def __init__(self,tag='',attrs=(),parent=None):self.tag=tag;self.a=dict(attrs);self.p=parent;self.c=[]
 def walk(self):
  yield self
  for x in self.c:
   if isinstance(x,N):yield from x.walk()
 def text(self,skip=False):
  if skip and self.tag in ['input','select','textarea','button','option']:return ''
  return ' '.join(x if isinstance(x,str) else x.text(skip) for x in self.c)
 def has(self,classes):return bool(set(self.a.get('class','').split())&set(classes))
class Parser(HTMLParser):
 def __init__(self):super().__init__();self.root=N();self.stack=[self.root]
 def handle_starttag(self,t,a):
  n=N(t,a,self.stack[-1]);self.stack[-1].c.append(n)
  if t not in ['input','img','br','hr','meta','link','source','wbr','area']:self.stack.append(n)
 def handle_endtag(self,t):
  for i in range(len(self.stack)-1,0,-1):
   if self.stack[i].tag==t:self.stack=self.stack[:i];break
 def handle_data(self,s):self.stack[-1].c.append(s)
def clean(s):return re.sub(r'\s+',' ',re.sub(r'\{\{.*?\}\}|\$\{.*?\}', '',str(s or ''))).strip(' :·—–')
def canon(s):return re.sub(r'\{\{.*?\}\}|\$\{.*?\}|(?<=\.)\d+(?=\.|$)','*',s)
def slug(s):return re.sub('[^a-zA-Z0-9]+','-',s).strip('-')
