fields={};rules={}
def field(scope,key,label,desc,topic=None,**extra):
 key=canon(key);id=scope+'--'+slug(key);fields[(scope,key)]=dict(id=id,kind='field',scope=scope,key=key,label=label,description=desc,topic=topic or topics[scope],**extra)
def rule(scope,selector,label,desc,topic=None):
 id=scope+'--'+slug(selector);rules[id]=dict(id=id,kind='control',scope=scope,selector=selector,label=label,description=desc,topic=topic or topics[scope])
def group(n):
 p=n.p
 while p and not(p.tag=='label' or p.has(['tsru-field','form-group','tsru-aha-config-field','tsru-combat-stat-row'])):p=p.p
 return p or n.p
