def infer(key,label,hint,scope):
 if key in D:return D[key]
 if hint and len(hint)>25:return hint
 k=key.lower();base=label or key
 if any(x in k for x in ['scale','zoom']):return f'{base} visual size in percent. 100% is base size. This changes the named display/crop, not token footprint or combat statistics.'
 if any(x in k for x in ['image','portrait','wallpaper','background','artwork','icon','overlay']):return f'{base}: Foundry-accessible artwork for this named interface slot. Its preview shows the saved placement; other portrait and token slots are configured separately. '+(hint or '')
 if 'font' in k:return f'{base}: typography for this named display. Use the stated units or a Foundry-accessible font file; this changes presentation rather than damage or resource values.'
 if any(x in k for x in ['color','gradient']):return f'{base}: color treatment for the named icon, frame, text or charge state. This is visual configuration, separate from mechanical Element matching.'
 if k.endswith(('x','y')) or 'offset' in k:return f'{base}: visual position in this editor’s stated units. Adjust its matching preview; this does not move a battle-map token.'
 if k.endswith('.id') or key in ['id','elementId','pathId']:return f'{base}: stable identifier or saved catalog selection used by this configuration. Existing characters and effects can reference it; changing a display name is different from changing its ID.'
 if k.endswith('.name') or key in ['name','title']:return f'{base}: display name for this saved entry in the current interface. It does not rename its linked world Actor or Item.'
 if 'order' in k:return f'{base}: sorting position for this catalog entry. This does not change initiative scores, charge layer order or reward quantity.'
 if 'search' in k:return f'{base}: narrow the visible entries without editing or deleting their saved definitions.'
 if hint:return f'{base}. {hint}'
 return f'{base} configures the named setting in {next(x[3] for x in SCOPES if x[0]==scope)}. Use the matching preview for display options and the guide below for its surrounding workflow.'
def topicFor(scope,key):
 if scope!='character':return topics[scope]
 for terms,topic in [(['HpCost'],'hp-costs'),(['Summon'],'summons'),(['alternate','Alternate'],'alternate-orbs'),(['enhanced','Enhanced'],'enhanced-form'),(['skill','Skill'],'skills'),(['talent','Talent'],'talents'),(['technique','Technique'],'techniques'),(['elation','Elation'],'aha'),(['boss','Boss'],'boss-phases'),(['break','Break'],'break'),(['splash','Splash','ultimateName','ultimateSubtitle'],'splash-art'),(['portrait','Portrait','Image','image','chargeColor','readyColor'],'artwork'),(['element','path'],'elements-paths'),(['Energy','current','max','regen','Gain'],'energy')]:
  if any(t in key for t in terms):return topic
 return 'settings-search'
for file in (ROOT/'templates').glob('*.hbs'):
 scope=SCOPE_FILES.get(file.stem)
 if not scope:continue
 p=Parser();p.feed(file.read_text())
 for n in p.root.walk():
  if n.tag in ['input','select','textarea'] and n.a.get('type') not in ['hidden','file']:
   key=n.a.get('name') or n.a.get('data-actor-field')
   if not key:continue
   w=group(n);nodes=list(w.walk());label=next((x for x in nodes if x.tag in ['strong','label']),w);caption=clean(label.text(True));hint=' '.join(clean(x.text()) for x in nodes if x.tag=='small' or x.has(['notes']))
   caption=caption.replace(hint,'').strip() if hint else caption
   if not caption or len(caption)>140:caption=clean(key)
   extra=dict(type=n.a.get('type',n.tag),source=str(file.relative_to(ROOT)))
   for k in ['min','max','step']:
    if n.a.get(k):extra[k]=n.a[k] if '{{' not in n.a[k] else 'configured limit'
   if n.tag=='select':extra['options']=[dict(value=x.a.get('value',''),label=clean(x.text())) for x in n.walk() if x.tag=='option']
   field(scope,key,caption,infer(canon(key),caption,hint,scope),topicFor(scope,key),**extra)
  if n.tag=='button':
   attrs=[(k,v) for k,v in n.a.items() if k.startswith('data-')]
   name=clean(n.text()) or clean(n.a.get('title')) or clean(n.a.get('aria-label'))
   if not attrs:continue
   key,val=attrs[0];selector='['+key+('="'+val+'"' if val and '{{' not in val else '')+']'
   if not name:name={'data-remove-type':'Remove mission type','data-remove-rarity':'Remove rarity','data-delete-quest':'Delete mission','data-remove-objective':'Remove objective','data-remove-reward':'Remove reward','data-remove-element':'Remove Element','data-remove-path':'Remove Path'}.get(key,clean(key.removeprefix('data-').replace('-',' ')).capitalize())
   low=name.lower()
   desc=({'save':'Apply the current editor’s configuration. This is separate from using an ability or spending its activation resource.','cancel':'Close without confirming this editor’s pending action. Already saved live changes are not undone.'}.get(low))
   if not desc:
    if low.startswith(('open ','configure ','edit ')):desc=name+' opens its corresponding configuration or editor. Opening it alone does not cast an ability or spend a resource.'
    elif low.startswith(('remove','delete','clear')):desc=name+' removes this named entry or reference from the current configuration. It does not delete the linked world Actor or Item unless explicitly stated by its live deletion workflow.'
    elif low.startswith(('save','apply')):desc=name+' applies the configuration or live action named on this button. Review the current profile, target and values before confirming; reading help does not activate it.'
    elif low.startswith(('preview','show','view','check')):desc=name+' displays the named preview, widget, text or inspection window. A preview does not change live charge or cast an ability.'
    elif low.startswith('add '):desc=name+' adds a new entry to this configuration so its details can be edited. It does not cast or distribute the linked content.'
    else:desc=name+' performs the named action in '+next(x[3] for x in SCOPES if x[0]==scope)+'. The guide describes its requirements and workflow.'
   rule(scope,selector,name,desc)
# Dynamic controls that are created by JavaScript rather than a .hbs field.
def dynamic(scope,attr,entries,topic=None):
 for key,label,desc in entries:rule(scope,f'[{attr}="{key}"]',label,desc,topic)
