# Explicit help for universal Actor/Item Multitype controls, including runtime-injected sheet panels.
for entry in reversed(json.loads(r'''[{"id":"multitype","selector":".tsru-multitype-settings,.tsru-multitype-combat,[data-multitype-open],[data-multitype-item-open]","topic":"multitype","label":"Actor Elements and Multitype"},{"id":"multitype-attacks","selector":".tsru-multitype-attacks","topic":"multitype","label":"Attack Element assignments"}]''')):
 scopes.insert(0,entry)
for entry in json.loads(r'''[{"id":"multitype--multitypeEnabled","kind":"field","scope":"multitype","key":"multitypeEnabled","label":"Multitype?","type":"checkbox","topic":"multitype","source":"templates/multitype-settings.hbs","description":"Enable an alternate Element system for this specific Actor, including PCs, NPCs and summoned creatures on every Path. ON reveals the mode switch. OFF uses the Actor’s current Assigned Element for future attacks, retaining saved Item/activity assignments and the last selected Actor Element. This GM control saves immediately."},{"id":"multitype--multitypeMode","kind":"field","scope":"multitype","key":"multitypeMode","label":"Multitype attacks / Type Changer","type":"checkbox","topic":"multitype","source":"templates/multitype-settings.hbs","description":"OFF selects Multitype attacks: activities and Items may choose independent HSR Elements, with the Actor Element as fallback. ON selects Type Changer: the GM switches the entire Actor’s current Element, and saved attack overrides are inactive. The selected mode’s label is emphasized. Saves immediately; switching keeps the other mode’s assignments."},{"id":"multitype--elementId","kind":"field","scope":"multitype","key":"elementId","label":"Assigned Element","type":"select","topic":"multitype","source":"templates/multitype-settings.hbs","description":"This specific Actor’s current HSR Element, used by ordinary attacks and unassigned attacks. Define choices in the Element Manager. In Type Changer, live changes update this same value. None removes its HSR Element. Saves immediately without changing Path, weakness definitions, charge or D&D5e damage types."},{"id":"character--elementId","kind":"field","scope":"character","key":"elementId","label":"Assigned Element","description":"The Actor’s current HSR Element. Saves immediately. Ordinary and unassigned attacks inherit it. Type Changer changes this same value from the GM/combat menus; Multitype attacks can override it per Item or activity. None clears the Element. Define choices in the Element Manager; this is separate from D&D5e damage types and target weaknesses.","topic":"multitype","type":"select","source":"templates/ultimate-tab.hbs","options":[{"value":"","label":"None"},{"value":"{{this.id}}","label":""}]}]'''):
 fields[(entry['scope'],entry['key'])]=entry
for entry in json.loads(r'''[{"id":"multitype--data-element-change","kind":"control","scope":"multitype","selector":"[data-element-change]","label":"Change Element now","description":"GM only: choose this row’s current HSR Element and save immediately. Requires Multitype? ON and Type Changer. PCs, NPCs and summons are supported. A Scene token row affects that unlinked token Actor; a world Actor change is shared by its linked tokens. Future attacks and supported Element visuals update; already captured rolls keep their Element. None clears the Element.","topic":"multitype"},{"id":"gm--data-element-change","kind":"control","scope":"gm","selector":"[data-element-change]","label":"Change Actor Element","description":"GM only: choose this row’s current HSR Element and save immediately. Requires Multitype? ON and Type Changer. PCs, NPCs and summons are supported. A Scene token row affects that unlinked token Actor; a world Actor change is shared by its linked tokens. Future attacks and supported Element visuals update; already captured rolls keep their Element. None clears the Element.","topic":"multitype"},{"id":"dm--data-element-change","kind":"control","scope":"dm","selector":"[data-element-change]","label":"Change Actor Element","description":"GM only: choose this row’s current HSR Element and save immediately. Requires Multitype? ON and Type Changer. PCs, NPCs and summons are supported. A Scene token row affects that unlinked token Actor; a world Actor change is shared by its linked tokens. Future attacks and supported Element visuals update; already captured rolls keep their Element. None clears the Element.","topic":"multitype"},{"id":"dm--data-dm-tab-elements","kind":"control","scope":"dm","selector":"[data-dm-tab=\"elements\"]","label":"Element Change tab","description":"Show live Element controls for configured Type Changers: PCs, NPCs and summoned/token Actors. Enable Multitype? and Type Changer in that specific Actor’s HSR Element Settings first. Choosing an Element in a row saves immediately.","topic":"multitype"},{"id":"multitype--data-multitype-attacks","kind":"control","scope":"multitype","selector":"[data-multitype-attacks]","label":"Assign attack Elements","description":"Open this Actor’s owned Items and activities. Set a default HSR Element on an Item or override one activity. Each selection saves immediately. Blank activities inherit the Item, then Actor. Assignments affect Toughness when Multitype? uses Multitype attacks; Type Changer retains them for later.","topic":"multitype"},{"id":"multitype--data-multitype-open","kind":"control","scope":"multitype","selector":"[data-multitype-open]","label":"HSR Element Settings","description":"Open Assigned Element, Multitype? and its two modes for this exact Actor. Available to the GM for every PC, NPC and summon. Open an unlinked token’s own sheet to configure that token independently; linked tokens use their shared world Actor.","topic":"multitype"},{"id":"multitype--data-multitype-item-open","kind":"control","scope":"multitype","selector":"[data-multitype-item-open]","label":"HSR Attack Elements","description":"Open Element assignments for this owned Item and its activities. Item defaults inherit the Actor; an activity can override the Item. Actor owners and GMs may edit these saved selections. Enable Multitype? → Multitype attacks on the Actor to use them for Toughness.","topic":"multitype"},{"id":"multitype--data-multitype-mode-label-attacks","kind":"control","scope":"multitype","selector":"[data-multitype-mode-label=\"attacks\"]","label":"Multitype attacks mode","description":"Mode switch OFF: each attack resolves activity override → Item override → Actor Element. Assignments are independent, so an Ice spell and Lightning weapon activity can belong to the same Fire Actor.","topic":"multitype"},{"id":"multitype--data-multitype-mode-label-changer","kind":"control","scope":"multitype","selector":"[data-multitype-mode-label=\"changer\"]","label":"Type Changer mode","description":"Mode switch ON: the GM changes the Actor’s live Assigned Element from its sheet, Star Rail GM Panel or DM Combat → Element Change. All new attacks use that Element while this mode is active.","topic":"multitype"},{"id":"multitype--data-multitype-status","kind":"control","scope":"multitype","selector":"[data-multitype-status]","label":"Element settings save status","description":"Confirms a live Element/mode save or describes an error. A failed save restores the previously stored controls, so the displayed switch reflects the Actor’s saved configuration.","topic":"multitype"},{"id":"multitype-attacks--data-attack-element-item","kind":"control","scope":"multitype-attacks","selector":"[data-attack-element-item]","label":"HSR Element for this Item or activity","description":"Select one HSR Element for this attack. The Item row is its default; an activity row overrides only that activity. Inherit Item / Actor uses the next parent’s choice. Changes save immediately and affect new rolls when Multitype attacks is active; D&D5e damage types, formulas and resistances are unchanged.","topic":"multitype"},{"id":"multitype-attacks--data-attack-element-activity","kind":"control","scope":"multitype-attacks","selector":"[data-attack-element-activity=\"\"]","label":"Item Element","description":"Default HSR Element for this owned Item. Every activity without a specific override inherits it. Inherit Actor uses the Actor’s current Assigned Element. Saves immediately. This selection does not change the Actor’s own Element.","topic":"multitype"},{"id":"multitype-attacks--data-multitype-attack-search","kind":"control","scope":"multitype-attacks","selector":"[data-multitype-attack-search]","label":"Find an Item or activity","description":"Filter this Actor’s list by Item and activity names. Multiple words narrow the results. Filtering only changes this local editor view; it does not change or erase any saved Element assignment.","topic":"multitype"},{"id":"multitype-attacks--data-multitype-attack-status","kind":"control","scope":"multitype-attacks","selector":"[data-multitype-attack-status]","label":"Attack Element save status","description":"Confirms the most recent Item/activity Element save. An error restores the previous dropdown selection. Choices persist on owned Items and remain stored when Multitype is disabled or Type Changer is selected.","topic":"multitype"}]'''):
 rules[entry['id']]=entry
(ROOT/'docs/controls.json').write_text(json.dumps(dict(schema=1,scopes=scopes,fields=list(fields.values()),rules=list(rules.values())),ensure_ascii=False,indent=2)+'\n')
print('Multitype reference:',len(fields)+len(rules))

# Compact shared Actor controls and allegiance meanings.
scopes.insert(0,json.loads(r'''{"id": "actor-controls", "selector": ".tsru-actor-config-controls", "topic": "npc-controls", "label": "Compact Actor sheet controls"}'''))
for entry in json.loads(r'''[{"id": "actor-controls--data-actor-control-toughness", "kind": "control", "scope": "actor-controls", "selector": "[data-actor-control=\"toughness\"]", "label": "Configure Toughness", "description": "Open this Actor’s current/max Toughness, weaknesses, NPC allegiance and initiative artwork. The dialog also provides a Multitype & Elements shortcut. Available on actual NPC and PC Actor sheets.", "topic": "weaknesses"}, {"id": "actor-controls--data-actor-control-multitype", "kind": "control", "scope": "actor-controls", "selector": "[data-actor-control=\"multitype\"]", "label": "Configure Multitype and Elements", "description": "Enable Multitype? on this exact PC, NPC or summoned Actor. Choose independent Item/activity attack Elements or live Type Changer. The same configuration is available from the Toughness dialog.", "topic": "multitype"}, {"id": "actor-controls--data-actor-control-boss", "kind": "control", "scope": "actor-controls", "selector": "[data-actor-control=\"boss\"]", "label": "Configure Boss Encounter", "description": "Open this Actor’s HSR settings, including boss phases, linked phase Actors, token sizes and boss HUD artwork. This opens configuration without starting a phase change.", "topic": "boss-phases"}, {"id": "actor-controls--data-actor-control-planar", "kind": "control", "scope": "actor-controls", "selector": "[data-actor-control=\"planar\"]", "label": "Planar Relics", "description": "Open the installed Planar module from a compact Actor-header icon. PC sheets open that character’s equipment, upgrades and set details. On NPC sheets the GM opens global set, currency and material configuration. Spell/Activity windows do not receive this Actor control.", "topic": "npc-controls"}, {"id": "actor-controls--data-actor-control-planar-stats", "kind": "control", "scope": "actor-controls", "selector": "[data-actor-control=\"planar-stats\"]", "label": "Original / Buffed stats", "description": "Switch this PC sheet between editable original scores and the read-only values after Planar bonuses. The icon tooltip names the current view; selecting a view does not rewrite the underlying original statistics.", "topic": "combat-stats"}, {"id": "actor-controls--data-npc-allegiance", "kind": "control", "scope": "actor-controls", "selector": "[data-npc-allegiance]", "label": "NPC Enemy / Ally", "description": "GM only. ON selects Ally: hide this NPC’s map/boss Toughness bar and weakness display, disable Toughness processing and use a blue initiative card. OFF selects Enemy: enable Toughness and use red. Saves immediately; retains current/max Toughness, weaknesses, HP and Ultimate/Multitype settings. A saved choice overrides old frame colors and token disposition. Unlinked/summoned token Actors change independently.", "topic": "npc-controls"}, {"id": "toughness--data-npc-allegiance", "kind": "control", "scope": "toughness", "selector": "[data-npc-allegiance]", "label": "NPC Enemy / Ally", "description": "GM only. ON selects Ally: hide this NPC’s map/boss Toughness bar and weakness display, disable Toughness processing and use a blue initiative card. OFF selects Enemy: enable Toughness and use red. Saves immediately; retains current/max Toughness, weaknesses, HP and Ultimate/Multitype settings. A saved choice overrides old frame colors and token disposition. Unlinked/summoned token Actors change independently.", "topic": "npc-controls"}, {"id": "actor-controls--data-npc-choice-ally", "kind": "control", "scope": "actor-controls", "selector": "[data-npc-choice=\"ally\"]", "label": "Ally mode", "description": "Switch ON selects Ally: the NPC uses a blue initiative frame and has no Toughness bar or Toughness reduction. Saved weakness and Toughness values remain available for a later return to Enemy.", "topic": "npc-controls"}, {"id": "actor-controls--data-npc-choice-enemy", "kind": "control", "scope": "actor-controls", "selector": "[data-npc-choice=\"enemy\"]", "label": "Enemy mode", "description": "Switch OFF selects Enemy: the NPC uses a red initiative frame and Toughness is enabled. This takes priority over an older custom frame color.", "topic": "npc-controls"}, {"id": "toughness--data-npc-choice-ally", "kind": "control", "scope": "toughness", "selector": "[data-npc-choice=\"ally\"]", "label": "Ally mode", "description": "Switch ON hides this NPC’s Toughness and uses a blue initiative frame; stored current/max and weakness values are retained.", "topic": "npc-controls"}, {"id": "toughness--data-npc-choice-enemy", "kind": "control", "scope": "toughness", "selector": "[data-npc-choice=\"enemy\"]", "label": "Enemy mode", "description": "Switch OFF enables this NPC’s Toughness and uses a red initiative frame. The switch saves immediately.", "topic": "npc-controls"}, {"id": "toughness--data-open-multitype-from-toughness", "kind": "control", "scope": "toughness", "selector": "[data-open-multitype-from-toughness]", "label": "Multitype & Elements", "description": "Open the same Actor’s Multitype? toggle, Multitype attacks / Type Changer switch and current HSR Element. This shortcut is also available as the shuffle icon beside Configure Toughness.", "topic": "multitype"}]'''):
 rules[entry['id']]=entry
(ROOT/'docs/controls.json').write_text(json.dumps(dict(schema=1,scopes=scopes,fields=list(fields.values()),rules=list(rules.values())),ensure_ascii=False,indent=2)+'\n')

# NPC portrait access and the live shared visual editor.
for scope,selector,label,description in [
 ('actor-controls','[data-actor-control="initiative"]','Format Initiative Portrait','GM only. Open the drag, zoom and flip editor for this NPC’s initiative tracker picture. Edits save to the source NPC and apply to its existing and future Ally/Enemy copies across scenes; portrait edits do not change allegiance, HP or Toughness.'),
 ('toughness','[data-open-npc-initiative-editor]','Format Initiative Portrait','Open the shared NPC initiative picture editor. Browse/drop artwork, drag to reposition, scroll to zoom and toggle Flip. Portrait edits save immediately, separately from the Toughness dialog’s Save button.'),
 ('initiative-art','[data-npc-initiative-sharing],[data-npc-initiative-sharing] strong','Shared NPC framing source','Names the source world NPC that receives portrait edits. Its existing and future token copies, including unlinked summons across scenes, use the same framing. Duplicated configured world Actors retain the source reference. Unlinked copies retain separate allegiance, HP, Toughness and stance; linked tokens continue to share their Actor’s combat state.'),
 ('initiative-art','[data-initiative-editor-stage],[data-initiative-editor-stage] button,[data-initiative-editor-stage] img','Initiative artwork preview','Drop an accessible image into this preview to replace the tracker portrait. Drag the card to reposition the artwork and scroll to zoom. The preview uses the tracker’s crop and flip. Every change saves automatically; for NPCs the artwork is shared by copies of the same source.'),
 ('initiative-art','.tsru-initiative-editor-status,.tsru-initiative-editor-status span','Portrait save status','Unsaved changes waits briefly before saving; Saving means a write is in progress. Saved confirms the artwork was stored. Save failed means the previous stored framing is still active; check permissions or retry an edit. Closing flushes pending changes.')]:
 id=scope+'--'+selector.split(',')[0].replace('[','').replace(']','').replace('"','').replace('=','-').replace('.','')
 rules[id]=dict(id=id,kind='control',scope=scope,selector=selector,label=label,description=description,topic='initiative')
for key,label,type,description,limits in [
 ('carouselImage','Initiative portrait','text','Browse or drop an accessible image path for this tracker portrait. Empty uses the source Actor portrait in the normal form, or normal artwork in the enhanced form.',{}),
 ('carouselImageX','Horizontal position','number','Move the artwork horizontally as a percentage of the initiative card width. 50 centers it; 0 is a valid offset. Larger zoom values allow additional travel.',{}),
 ('carouselImageY','Vertical position','number','Move the artwork vertically as a percentage of the initiative card height. 50 centers it. Drag the preview for visual placement.',{}),
 ('carouselImageScale','Portrait zoom','number','Set image zoom as a percentage: 100 is its normal contained size. Scroll over the preview to adjust by five percentage points.',{'min':50,'max':800}),
 ('carouselImageFlip','Flip portrait','checkbox','Mirror the tracker portrait horizontally. This changes the artwork presentation and does not change token facing or map artwork.',{})]:
 id='initiative-art--'+key
 fields[id]=dict(id=id,kind='field',scope='initiative-art',key=key,label=label,description=description+' Changes save automatically. NPCs share this value through their source Actor, independently for normal and enhanced framing.',topic='initiative',type=type,source='scripts/module.js',**limits)

# Explicit authored meanings for both spell sources and temporary summon health.
for selector,label,description in [
 ('[data-spell-enabled]','Casts spell?','After the Skill pays its configured SP/actual HP costs, cast a real owned spell as this character. Cancelled or blocked casting refunds those costs. OFF keeps the normal descriptive Skill.'),
 ('[data-spell-mode],[data-spell-mode-label]','Spell source: Spell known / Other','Flip OFF for Spell known, which selects an existing character spell. Flip ON for Other, which accepts a compendium spell by drag and drop. Both saved choices are retained when switching; this switch saves immediately.'),
 ('[data-spell-known]','Spell known','Choose a spell Item already owned by this character. The Skill uses its native spell activity with the character as caster. Removing that spell requires selecting another one.'),
 ('[data-spell-drop]','Other: compendium spell','Drop a spell Item from a compendium. The first cast imports an owned copy onto this character; subsequent casts reuse it. Actors, features and world Items are rejected. The source compendium is unchanged.'),
 ('[data-spell-open]','Open spell','Inspect the selected compendium spell without casting it or spending resources. Disabled until a source spell has been dropped.'),
 ('[data-spell-clear]','Clear spell','Clear the Other source reference. This does not delete the compendium spell or an already imported character-owned copy. Disabled without a source selection.')]:rule('character',selector,label,description,'skill-spells')
for key,label,description in [
 ('enabled','Has a memosprite?','Enable the saved companion HUD on any Path. A live spell or ability summon can also temporarily display its own health and portrait; update both Ultimates and Memosprites for that integration.'),
 ('hp','Current HP','Before summoning, linked source Actor HP is a configuration preview. During a live summon, the exact placed token Actor supplies HP and disables this input. At zero HP or removal its HP arc hides and saved defaults return.'),
 ('maxHp','Maximum HP','Live HP arc capacity comes from the active summoned token Actor’s maximum HP. Before summoning, a valid linked Actor supplies a preview; otherwise the configured default is used. Editing this field does not edit a live token.'),
 ('portrait','Circular companion portrait','Saved default HUD portrait and crop. An external spell or ability summon temporarily supplies its own colored artwork without overwriting this setting. At zero HP or removal this default returns.')]:
 for entry in fields.values():
  if entry.get('scope')=='memosprite' and entry.get('key')==key:entry.update(label=label,description=description,topic='memosprite-summoning')

current=dict(schema=1,scopes=scopes,fields=list(fields.values()),rules=list(rules.values()))
for kind in ['scopes','fields','rules']:
 fresh={entry['id']:entry for entry in current[kind]};rows=[]
 for prior in PREVIOUS_REFERENCE.get(kind,[]):
  entry=fresh.pop(prior['id'],None)
  if entry is not None:rows.append({**{key:entry[key] for key in prior if key in entry},**{key:value for key,value in entry.items() if key not in prior}})
 rows.extend(fresh.values());current[kind]=rows
(ROOT/'docs/controls.json').write_text(json.dumps(current,ensure_ascii=False,indent=2)+'\n')
